import { sql } from 'drizzle-orm';
import {
  bigint,
  boolean,
  check,
  date,
  index,
  integer,
  jsonb,
  pgEnum,
  pgTable,
  text,
  timestamp,
  uniqueIndex,
  uuid,
  type AnyPgColumn,
} from 'drizzle-orm/pg-core';

/*
 * Leo & Associates content schema.
 *
 * Conventions
 * - UUID primary keys generated by Postgres (gen_random_uuid()).
 * - Foreign keys default to NO ACTION / RESTRICT: published music records are
 *   archived, never cascaded away. The only cascade is release_credits -> its
 *   owning release/track, because a credit has no meaning without its parent.
 * - Audio and artwork bytes live in object storage; media_assets holds metadata.
 * - created_by / updated_by reference admin_users, which are disabled rather
 *   than deleted so audit history stays intact.
 */

export const contentStatus = pgEnum('content_status', ['draft', 'published', 'archived']);
export const releaseType = pgEnum('release_type', ['single', 'ep', 'album']);
export const playbackMode = pgEnum('playback_mode', ['full', 'preview', 'unavailable']);
export const adminRole = pgEnum('admin_role', ['OWNER', 'EDITOR']);
export const adminStatus = pgEnum('admin_status', ['invited', 'active', 'disabled']);
export const mediaKind = pgEnum('media_kind', ['artwork', 'image', 'audio_master', 'audio_playback']);
export const mediaVisibility = pgEnum('media_visibility', ['private', 'public']);
export const mediaStatus = pgEnum('media_status', ['pending', 'ready', 'failed', 'deleted']);
export const platform = pgEnum('platform', [
  'apple_music',
  'spotify',
  'youtube_music',
  'amazon_music',
  'tidal',
  'bandcamp',
  'soundcloud',
  'shopify',
  'other',
]);

const timestamps = {
  createdAt: timestamp('created_at', { withTimezone: true }).notNull().defaultNow(),
  updatedAt: timestamp('updated_at', { withTimezone: true })
    .notNull()
    .defaultNow()
    .$onUpdate(() => new Date()),
};

export const adminUsers = pgTable(
  'admin_users',
  {
    id: uuid('id').primaryKey().defaultRandom(),
    // Null until the invited person first signs in with a verified matching email.
    clerkUserId: text('clerk_user_id').unique(),
    email: text('email').notNull(),
    displayName: text('display_name'),
    role: adminRole('role').notNull(),
    status: adminStatus('status').notNull().default('invited'),
    // Editors may publish only when an owner explicitly grants it.
    canPublish: boolean('can_publish').notNull().default(false),
    invitedById: uuid('invited_by_id').references((): AnyPgColumn => adminUsers.id),
    lastSignInAt: timestamp('last_sign_in_at', { withTimezone: true }),
    disabledAt: timestamp('disabled_at', { withTimezone: true }),
    ...timestamps,
  },
  t => [
    uniqueIndex('admin_users_email_lower_key').on(sql`lower(${t.email})`),
    check('admin_users_email_shape', sql`${t.email} ~ '^[^@\\s]+@[^@\\s]+$'`),
  ],
);

export const mediaAssets = pgTable(
  'media_assets',
  {
    id: uuid('id').primaryKey().defaultRandom(),
    kind: mediaKind('kind').notNull(),
    visibility: mediaVisibility('visibility').notNull().default('private'),
    status: mediaStatus('status').notNull().default('pending'),
    storageProvider: text('storage_provider').notNull(),
    bucket: text('bucket').notNull(),
    // Unguessable key (UUID-based); never derived from release titles.
    objectKey: text('object_key').notNull(),
    originalFilename: text('original_filename'),
    mimeType: text('mime_type').notNull(),
    byteSize: bigint('byte_size', { mode: 'number' }).notNull(),
    checksumSha256: text('checksum_sha256'),
    width: integer('width'),
    height: integer('height'),
    durationMs: integer('duration_ms'),
    altText: text('alt_text'),
    replacedById: uuid('replaced_by_id').references((): AnyPgColumn => mediaAssets.id),
    uploadedById: uuid('uploaded_by_id').references(() => adminUsers.id),
    deletedAt: timestamp('deleted_at', { withTimezone: true }),
    ...timestamps,
  },
  t => [
    uniqueIndex('media_assets_bucket_key_key').on(t.bucket, t.objectKey),
    index('media_assets_kind_status_idx').on(t.kind, t.status),
    check('media_assets_byte_size_positive', sql`${t.byteSize} > 0`),
    // Masters can never be marked public.
    check('media_assets_master_private', sql`${t.kind} <> 'audio_master' OR ${t.visibility} = 'private'`),
  ],
);

export const artists = pgTable(
  'artists',
  {
    id: uuid('id').primaryKey().defaultRandom(),
    slug: text('slug').notNull().unique(),
    name: text('name').notNull(),
    bio: text('bio'),
    imageAssetId: uuid('image_asset_id').references(() => mediaAssets.id),
    status: contentStatus('status').notNull().default('draft'),
    publishedAt: timestamp('published_at', { withTimezone: true }),
    createdById: uuid('created_by_id').references(() => adminUsers.id),
    updatedById: uuid('updated_by_id').references(() => adminUsers.id),
    ...timestamps,
  },
  t => [
    index('artists_status_idx').on(t.status),
    check('artists_slug_shape', sql`${t.slug} ~ '^[a-z0-9]+(-[a-z0-9]+)*$'`),
  ],
);

export const releases = pgTable(
  'releases',
  {
    id: uuid('id').primaryKey().defaultRandom(),
    slug: text('slug').notNull().unique(),
    title: text('title').notNull(),
    type: releaseType('type').notNull(),
    status: contentStatus('status').notNull().default('draft'),
    primaryArtistId: uuid('primary_artist_id')
      .notNull()
      .references(() => artists.id),
    // Nullable on purpose: never invent a release date.
    releaseDate: date('release_date'),
    description: text('description'),
    coverAssetId: uuid('cover_asset_id').references(() => mediaAssets.id),
    catalogueNumber: text('catalogue_number').unique(),
    upc: text('upc').unique(),
    publishedAt: timestamp('published_at', { withTimezone: true }),
    archivedAt: timestamp('archived_at', { withTimezone: true }),
    createdById: uuid('created_by_id').references(() => adminUsers.id),
    updatedById: uuid('updated_by_id').references(() => adminUsers.id),
    ...timestamps,
  },
  t => [
    index('releases_status_date_idx').on(t.status, t.releaseDate),
    index('releases_primary_artist_idx').on(t.primaryArtistId),
    check('releases_slug_shape', sql`${t.slug} ~ '^[a-z0-9]+(-[a-z0-9]+)*$'`),
    check('releases_published_has_timestamp', sql`${t.status} <> 'published' OR ${t.publishedAt} IS NOT NULL`),
  ],
);

export const tracks = pgTable(
  'tracks',
  {
    id: uuid('id').primaryKey().defaultRandom(),
    releaseId: uuid('release_id')
      .notNull()
      .references(() => releases.id),
    discNumber: integer('disc_number').notNull().default(1),
    position: integer('position').notNull(),
    title: text('title').notNull(),
    durationMs: integer('duration_ms'),
    isrc: text('isrc'),
    explicit: boolean('explicit'),
    playbackMode: playbackMode('playback_mode').notNull().default('unavailable'),
    // Public, transcoded playback file. Masters are tracked separately and never served.
    playbackAssetId: uuid('playback_asset_id').references(() => mediaAssets.id),
    masterAssetId: uuid('master_asset_id').references(() => mediaAssets.id),
    previewStartMs: integer('preview_start_ms'),
    previewDurationMs: integer('preview_duration_ms'),
    ...timestamps,
  },
  t => [
    uniqueIndex('tracks_release_disc_position_key').on(t.releaseId, t.discNumber, t.position),
    uniqueIndex('tracks_isrc_key').on(t.isrc),
    check('tracks_position_positive', sql`${t.position} > 0 AND ${t.discNumber} > 0`),
    check('tracks_duration_positive', sql`${t.durationMs} IS NULL OR ${t.durationMs} > 0`),
    check(
      'tracks_playable_has_asset',
      sql`${t.playbackMode} = 'unavailable' OR ${t.playbackAssetId} IS NOT NULL`,
    ),
  ],
);

export const releaseCredits = pgTable(
  'release_credits',
  {
    id: uuid('id').primaryKey().defaultRandom(),
    releaseId: uuid('release_id')
      .notNull()
      .references(() => releases.id, { onDelete: 'cascade' }),
    // Null = release-level credit; set = credit for one track on this release.
    trackId: uuid('track_id').references(() => tracks.id, { onDelete: 'cascade' }),
    artistId: uuid('artist_id').references(() => artists.id),
    name: text('name').notNull(),
    role: text('role').notNull(),
    position: integer('position').notNull().default(0),
    ...timestamps,
  },
  t => [
    index('release_credits_release_idx').on(t.releaseId, t.position),
    index('release_credits_track_idx').on(t.trackId),
  ],
);

export const platformLinks = pgTable(
  'platform_links',
  {
    id: uuid('id').primaryKey().defaultRandom(),
    // Exactly one owner: a release, a track, or an artist.
    releaseId: uuid('release_id').references(() => releases.id),
    trackId: uuid('track_id').references(() => tracks.id),
    artistId: uuid('artist_id').references(() => artists.id),
    platform: platform('platform').notNull(),
    url: text('url').notNull(),
    label: text('label'),
    position: integer('position').notNull().default(0),
    isActive: boolean('is_active').notNull().default(true),
    verifiedAt: timestamp('verified_at', { withTimezone: true }),
    verifiedById: uuid('verified_by_id').references(() => adminUsers.id),
    ...timestamps,
  },
  t => [
    check(
      'platform_links_single_owner',
      sql`num_nonnulls(${t.releaseId}, ${t.trackId}, ${t.artistId}) = 1`,
    ),
    check('platform_links_https', sql`${t.url} ~ '^https://'`),
    uniqueIndex('platform_links_release_platform_key')
      .on(t.releaseId, t.platform)
      .where(sql`${t.releaseId} IS NOT NULL AND ${t.platform} <> 'other'`),
    uniqueIndex('platform_links_track_platform_key')
      .on(t.trackId, t.platform)
      .where(sql`${t.trackId} IS NOT NULL AND ${t.platform} <> 'other'`),
    uniqueIndex('platform_links_artist_platform_key')
      .on(t.artistId, t.platform)
      .where(sql`${t.artistId} IS NOT NULL AND ${t.platform} <> 'other'`),
  ],
);

/*
 * Structured website copy. Each key (home, about, footer, social, label) holds a
 * Zod-validated JSON document. Editors write `draft`; publishing copies it to
 * `published`. Public pages only ever read `published`.
 */
export const siteContent = pgTable('site_content', {
  id: uuid('id').primaryKey().defaultRandom(),
  key: text('key').notNull().unique(),
  draft: jsonb('draft').notNull().default({}),
  published: jsonb('published'),
  version: integer('version').notNull().default(1),
  publishedAt: timestamp('published_at', { withTimezone: true }),
  updatedById: uuid('updated_by_id').references(() => adminUsers.id),
  publishedById: uuid('published_by_id').references(() => adminUsers.id),
  ...timestamps,
});

/* Append-only: the migration installs a trigger that rejects UPDATE and DELETE. */
export const auditLogs = pgTable(
  'audit_logs',
  {
    id: uuid('id').primaryKey().defaultRandom(),
    actorAdminId: uuid('actor_admin_id').references(() => adminUsers.id),
    // Kept even when the actor has no admin record (e.g. a denied sign-in).
    actorClerkUserId: text('actor_clerk_user_id'),
    action: text('action').notNull(),
    entityType: text('entity_type').notNull(),
    entityId: uuid('entity_id'),
    metadata: jsonb('metadata').notNull().default({}),
    createdAt: timestamp('created_at', { withTimezone: true }).notNull().defaultNow(),
  },
  t => [
    index('audit_logs_entity_idx').on(t.entityType, t.entityId),
    index('audit_logs_created_idx').on(t.createdAt),
    index('audit_logs_actor_idx').on(t.actorAdminId),
  ],
);

export type AdminUser = typeof adminUsers.$inferSelect;
export type AdminRole = (typeof adminRole.enumValues)[number];
export type AuditLogInsert = typeof auditLogs.$inferInsert;
